(6287776, 929692, 67258, '<td valign="top">More than any other photo in the challenge, this illustrated the concept of work to me best. Very disappointing to see it scoring so low.</td>', 'More than any other photo in the challenge, this illustrated the concept of work to me best. Very disappointing to see it scoring so low.', '2011-01-19 03:29:14.000000', NULL, 0),
(6287777, 929620, 100002, '<td valign="top">WOOOW... my first ribbon!!!!<br/>Thanks to all for the votes and nice comments!!!<br/>It is really awesome, if you see your picture on the first page :)<br/> <br/>This picture was taken on a beautiful location here in Munich Germany! <br/>//www.schloesser-schleissheim.de/<br/> <br/>DANKE!</td>', 'WOOOW... my first ribbon!!!!Thanks to all for the votes and nice comments!!!It is really awesome, if you see your picture on the first page :) This picture was taken on a beautiful location here in Munich Germany! //www.schloesser-schleissheim.de/ DANKE!', '2011-01-19 03:31:16.000000', NULL, 0),
(6287791, 928700, 48954, '<td valign="top">wow. excellent</td>', 'wow. excellent', '2011-01-19 04:01:04.000000', NULL, 0),
