(6287802, 929620, 108069, '<td valign="top">Congratulations! Fabulous image.</td>', 'Congratulations! Fabulous image.', '2011-01-19 04:26:21.000000', NULL, 0),
(6287805, 929083, 20799, '<td valign="top">Hey Rosie, I voted but somehow didn''t leave a comment so here it is. You had a 9 from me for this excellent work. I knew this poster and you did a great job redoing it. The colors are perfect! Congratulations, great shot.</td>', 'Hey Rosie, I voted but somehow didn''t leave a comment so here it is. You had a 9 from me for this excellent work. I knew this poster and you did a great job redoing it. The colors are perfect! Congratulations, great shot.', '2011-01-19 04:33:41.000000', NULL, 0),
(6287808, 929363, 98349, '<td valign="top">Thanks for all the comments and votes. This is by far the highest I have finished. :) After looking at the comments there are a few things I need to look out for. Now over time I am determined to get on that front page!!</td>', 'Thanks for all the comments and votes. This is by far the highest I have finished. :) After looking at the comments there are a few things I need to look out for. Now over time I am determined to get on that front page!!', '2011-01-19 04:35:03.000000', NULL, 0),
(6287819, 929357, 20799, '<td valign="top">Well you had a 10 from me. For the effort but also for the idea of a dream job I could relate to. I''ve seen this shot done with big machines and it''s amazing that you have achieved almost the same quality.</td>', 'Well you had a 10 from me. For the effort but also for the idea of a dream job I could relate to. I''ve seen this shot done with big machines and it''s amazing that you have achieved almost the same quality.', '2011-01-19 04:54:15.000000', NULL, 0),
(6287821, 929449, 20799, '<td valign="top">You work here?! Wow! So you already are at your dream job. I guessed this was from the viewing gallery (although the angle looks a bit lower than other photos I''ve seen, you might be somewhere else with your employee pass :). Anyway, not only a great location but a perfect shot too. I gave you a 10.<br/>My son just saw this photo and reminded me that he has his name on that chip going to Mars.</td>', 'You work here?! Wow! So you already are at your dream job. I guessed this was from the viewing gallery (although the angle looks a bit lower than other photos I''ve seen, you might be somewhere else with your employee pass :). Anyway, not only a great location but a perfect shot too. I gave you a 10.My son just saw this photo and reminded me that he has his name on that chip going to Mars.', '2011-01-19 05:06:26.000000', NULL, 0),
(6287829, 929478, 119232, '<td valign="top"><i>Thumbs up :)</i></td>', 'Thumbs up :)', '2011-01-19 05:18:44.000000', NULL, 0),
(6287834, 929357, 108069, '<td valign="top">I didn''t vote on this one because I honestly couldn''t quite figure it out so I thought it best to leave it alone. Seems like others also couldn''t figure it out but tagged it with a 1 because of it. Now that Abra has pointed it out on another thread I''m really glad I came back to it and really impressed with what you''ve done here. Awesome job.</td>', 'I didn''t vote on this one because I honestly couldn''t quite figure it out so I thought it best to leave it alone. Seems like others also couldn''t figure it out but tagged it with a 1 because of it. Now that Abra has pointed it out on another thread I''m really glad I came back to it and really impressed with what you''ve done here. Awesome job.', '2011-01-19 05:38:18.000000', NULL, 0),
(6287864, 929478, 33361, '<td valign="top">LOVE this!!</td>', 'LOVE this!!', '2011-01-19 06:44:15.000000', NULL, 0);
